<?php
declare(strict_types=1);require_once __DIR__.'/../config/api.php';if($_SERVER['REQUEST_METHOD']!=='GET')respond(['success'=>false,'message'=>'Method not allowed'],405);$u=requireUser($pdo);$s=$pdo->prepare("SELECT a.id application_id,a.status,a.applied_at,a.reviewed_at,a.rejection_reason,v.id vacancy_id,v.title,v.payout_amount,v.payout_period,h.id hotel_id,h.name hotel_name,h.city,c.name category_name,r.name job_role_name FROM applications a INNER JOIN vacancies v ON v.id=a.vacancy_id INNER JOIN hotels h ON h.id=v.hotel_id INNER JOIN categories c ON c.id=v.category_id INNER JOIN job_roles r ON r.id=v.job_role_id WHERE a.user_id=? ORDER BY a.applied_at DESC");$s->execute([$u['user_id']]);respond(['success'=>true,'data'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
